ProjectALife.DialogueShards["scenes_panic_days_1"] = {
{"fw_ld7_pca_0001","panic_days",2,"reg=civilian,family,worker,rescue|tmp=fresh|day=0,4|mood=fear",{1,"Somebody's gonna jump out, right? Somebody's gonna jump out and say it's a joke",2,"Nobody's jumping out",1,"I know, I KNOW, I just keep standing here waiting",2,"I looked behind the dumpster, I'm not even kidding, I looked"}},
{"fw_ld7_pca_0002","panic_days",2,"reg=civilian,family,worker,rescue|tmp=fresh|day=0,4|mood=fear",{1,"That's Mr. Hadley, that's- I waved at that man every morning for six years",2,"Don't say his name",1,"He's still got his bathrobe on, he's walking around in his ROBE",2,"Stop looking at him, look at me, look at ME"}},
{"fw_ld7_pca_0003","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=grim",{1,"There's the beep again, that long beep, and then nothing",2,"It's the emergency system, it's supposed to say what to do",1,"Then WHY DOESN'T IT",2,"Maybe the guy who reads it went home to his family"}},
{"fw_ld7_pca_0004","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=fear",{1,"Trucker on the CB says Louisville's shut down, every bridge, soldiers on all of 'em",2,"Truckers say all kinds of crap",1,"He was crying, though, I never heard a trucker cry on the radio",2,"...okay, that's different, that's- okay"}},
{"fw_ld7_pca_0005","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=fear",{1,"Sherry's not picking up, I've called forty times, it just RINGS",2,"Everybody's calling everybody, the lines are jammed",1,"Jammed goes busy, mine rings and rings and rings",2,"Then she's out, she's out running around, she's fine, she's fine"}},
{"fw_ld7_pca_0006","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=angry",{1,"It's the heat, I'm telling you, folks lose their minds in this heat",2,"Heat don't make a man get back up",1,"You don't know that, you weren't even-",2,"I was three feet from him! THREE FEET!"}},
{"fw_ld7_pca_0007","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=grim",{1,"Dennis says it's just a scratch, he won't let nobody look at it",2,"Then it ain't a scratch",1,"He's got a fever, his shirt's sweated clean through",2,"Keep the kids off him, I'm sorry, I know he's your sister's husband"}},
{"fw_ld7_pca_0008","panic_days",2,"reg=civilian,family,worker,rescue|tmp=fresh|day=0,4|mood=fear",{1,"Kill the lamp! Kill it, kill it!",2,"It's one little lamp",1,"They'll SEE it, they see everything that's lit up",2,"Fine- fine, it's off... Jesus, I can't see my own hand"}},
{"fw_ld7_pca_0009","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=sad",{1,"Jacob asked me when school starts back",2,"What'd you tell him?",1,"I said soon, real soon, like a damn idiot",2,"He's seven, what were you gonna say, never?"}},
{"fw_ld7_pca_0010","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=angry",{1,"Wal-Mart in Radcliff was a zoo, some lady took a swing at me over D batteries",2,"Did you give 'em up?",1,"Hell no, I got four flashlights and nothing to put in 'em",2,"Everybody's fighting over stuff they don't even need yet"}},
{"fw_ld7_pca_0011","panic_days",2,"reg=civilian,family,worker,rescue|tmp=fresh|day=0,4|mood=fear",{1,"I sat in my closet for an hour holding a skillet",2,"A skillet?",1,"It was the first thing I grabbed, don't laugh at me",2,"I'm not, I'd have grabbed the toaster, no lie"}},
{"fw_ld7_pca_0012","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=calm",{1,"Maybe we just wait it out? Stay put and wait it out?",2,"For what?",1,"The Guard, the state, I don't know, somebody",2,"I been waiting for somebody since it started, ain't nobody come"}},
{"fw_ld7_pca_0013","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=sad",{1,"I think I left the gas on",2,"So?",1,"So it'll burn the whole house down, Mama always said-",2,"Let it, who cares, don't you dare go back in there"}},
{"fw_ld7_pca_0014","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=angry",{1,"Gas line went clear around the block and then the pump just quit",2,"Guy ahead of me had a shotgun in his lap, I didn't say a word",1,"Nobody said a word, half of 'em were crying",2,"I drove home on fumes and my hands still ain't right"}},
{"fw_ld7_pca_0015","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=fear",{1,"Why won't Duke shut up, every dog on the hill's going at once",2,"They smell something",1,"Smell WHAT?",2,"I don't wanna know, bring him in, bring him in and hold his mouth"}},
{"fw_ld7_pca_0016","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=grim",{1,"Helicopter went over so low my teeth rattled, never even slowed down",2,"They saw us",1,"They saw us and kept going",2,"They've got somewhere to be, they have to, there's gotta be somewhere"}},
{"fw_ld7_pca_0017","panic_days",2,"reg=civilian,family,worker,rescue|tmp=fresh|day=0,4|mood=fear",{1,"The sirens stopped",2,"Is that good?",1,"They ran all day and now they just quit, why would they quit?",2,"Maybe nobody's left to drive 'em"}},
{"fw_ld7_pca_0018","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=grim",{1,"You smell that? Over by the Kroger?",2,"I been breathing through my mouth since noon",1,"Something died, a LOT of somethings",2,"Don't tell me it's the heat, don't you tell me it's the heat"}},
{"fw_ld7_pca_0019","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=sad",{1,"When our freezer failed, Mama said to eat the ice cream first",2,"My mama taught me that too",1,"Whole day's gone to hell and you're worried about ice cream",2,"One small thing she could do something about. I understand that now"}},
{"fw_ld7_pca_0020","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=sad",{1,"Preacher says we ought to pray",2,"I did, prayed till my knees went numb",1,"And?",2,"And then somebody screamed, so I quit for a minute"}},
{"fw_ld7_pca_0021","panic_days",2,"reg=civilian,family,worker,rescue|tmp=fresh|day=0,4|mood=fear",{1,"Where's Emma? She was RIGHT HERE, she was right here a second ago!",2,"Table, she's under the table, look",1,"Baby, come on out, it's okay, come on",2,"She won't say nothing, she hasn't said a word since we ran"}},
{"fw_ld7_pca_0022","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=calm",{1,"In '37 the water came up to the second floor, I remember that, I was a boy",2,"Where'd y'all go?",1,"Church, the whole town waited it out in the church, so I know about waiting",2,"But this ain't water"}},
{"fw_ld7_pca_0023","panic_days",2,"reg=civilian,family,worker,rescue|tmp=fresh|day=0,4|mood=fear",{1,"I gotta find my friends, they're at Kenny's, it's like a mile",2,"You are NOT walking a mile",1,"You can't stop me, I'm eighteen!",2,"Eighteen's not bulletproof, sit down, SIT DOWN"}},
{"fw_ld7_pca_0024","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=sad",{1,"Mama's heart pills are in her purse and her purse is in Louisville",2,"How many has she got left?",1,"Four, she's got four days, I don't even know where she is",2,"Then we find a drugstore, today, now"}},
{"fw_ld7_pca_0025","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=grim",{1,"Mr. Sykes is up on his roof with the deer rifle, watching the whole block",2,"Good, somebody should",1,"He hasn't moved in six hours, I'm starting to wonder if he's alright",2,"Go check",1,"YOU go check"}},
{"fw_ld7_pca_0026","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=angry",{1,"Somebody's cleaning out the whole Rite Aid, I can see 'em from here",2,"People are scared, they're taking what they need",1,"What they need? They've got shopping carts!",2,"Nobody's gonna stop 'em, so what's the use of getting mad"}},
{"fw_ld7_pca_0027","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=grim",{1,"Who's got a gun? Somebody HAS to have a gun",2,"My daddy's twelve-gauge, it's in the truck",1,"Shells?",2,"Four, and I don't really know how to load it, so now you know"}},
{"fw_ld7_pca_0028","panic_days",2,"reg=civilian,family,worker,rescue|tmp=fresh|day=0,4|mood=fear",{1,"Count off! One!",2,"Two!",1,"Three- THREE- where's three? Where's Pete?",2,"He was behind me, he was right behind me, I heard him",1,"PETE?! PETE!"}},
{"fw_ld7_pca_0029","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=fear",{1,"Is it in the water, you think? Could it get in the water?",2,"Nobody said that",1,"Nobody's said ANYTHING, that's what's scaring me",2,"Fine, we boil it, we boil all of it, we'll worry later"}},
{"fw_ld7_pca_0030","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=grim",{1,"Don't touch nothing, don't touch the rail, don't touch your face",2,"How do you know that helps?",1,"I don't, I'm doing it anyway",2,"Fine, I'm sitting on my hands"}},
{"fw_ld7_pca_0031","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=fear",{1,"North is Louisville and Louisville's worse",2,"Who told you that?",1,"Everybody who comes from there is covered in dust and won't stop walking",2,"Then we go anywhere but north"}},
{"fw_ld7_pca_0032","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=calm",{1,"They're saying get to the high school, then they're saying stay home",2,"Which one is it?",1,"I think whoever's saying it is guessing",2,"I'll guess home, then, I know where my shoes are"}},
{"fw_ld7_pca_0033","panic_days",2,"reg=civilian,family,worker,rescue|tmp=fresh|day=0,4|mood=fear",{1,"Three pops in a row, that's nobody's firecrackers",2,"Somebody's out hunting",1,"Nobody hunts in July, nobody hunts in town",2,"I know, I'm saying it for me, I need to hear it said"}},
{"fw_ld7_pca_0034","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=sad",{1,"Grandpa won't leave the farm, he's out there with a shotgun and a Bible",2,"He's seventy-nine!",1,"He says somebody's gotta feed the cattle",2,"There's no cattle left, he knows that, he's out there anyway"}},
{"fw_ld7_pca_0035","panic_days",2,"reg=civilian,family,worker,rescue|tmp=fresh|day=0,4|mood=funny",{1,"Hahaha, I got a haircut last week! A haircut! Who does that before THIS?",2,"Looks good, though",1,"Looks great, I'll die handsome, hahaha- ha...",2,"Stop, you're doing the thing where you laugh and then it turns"}},
{"fw_ld7_pca_0036","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=fear",{1,"Our Father who art in heaven, hallowed be- how's it go after that",2,"Thy name- no, thy kingdom come",1,"Thy kingdom come, thy will be done...",2,"Keep going, don't stop, I'm not done listening"}},
{"fw_ld7_pca_0037","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=grim",{1,"My brother's got a scanner, it's all ten-codes and screaming",2,"Turn it down!",1,"I can't, it's the only thing telling us anything",2,"Then at least turn it low, they hear stuff"}},
{"fw_ld7_pca_0038","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=angry",{1,"I put a quarter in the payphone at the Shell and got nothing, not even a dial tone",2,"They didn't cut ALL the lines",1,"Sure sounds like it, dead as a rock",2,"It ate my quarter, I want my quarter back!"}},
{"fw_ld7_pca_0039","panic_days",2,"reg=civilian,family,worker,rescue|tmp=fresh|day=0,4|mood=fear",{1,"Shh, shhh, don't breathe",2,"I'm not",1,"You're breathing, I can hear you",2,"I have to breathe, I'm a PERSON"}},
{"fw_ld7_pca_0040","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=sad",{1,"The Hendersons were right across from us and we didn't even knock",2,"We couldn't have",1,"Their kids were home, I saw the light on",2,"I know, I know, I think about that light"}},
{"fw_ld7_pca_0041","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=fear",{1,"I thought it was a fight at first, some drunks outside the VFW",2,"And then?",1,"And then one kept going after the other one got up",2,"Stop, I don't want the rest of it"}},
{"fw_ld7_pca_0042","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=grim",{1,"Phones are dead, TV's static, radio's just hiss",2,"There's still the AM",1,"The AM's a preacher yelling about Revelation",2,"...he might be right, how would we know"}},
{"fw_ld7_pca_0043","panic_days",2,"reg=civilian,family,worker,rescue|tmp=fresh|day=0,4|mood=fear",{1,"I can't make my hands stop, watch, they just keep going",2,"Mine too",1,"I couldn't even work a lighter last time I tried",2,"Don't force it. Take a breath. You don't have to prove anything with your hands"}},
{"fw_ld7_pca_0044","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=sad",{1,"I haven't slept in two days",2,"Sleep, I'll watch",1,"I close my eyes and I see the Pruitts' yard",2,"Then keep 'em open, just rest 'em, I'll count for you"}},
{"fw_ld7_pca_0045","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=fear",{1,"It might be in our house already, somebody check everybody",2,"Check what?",1,"Arms and necks, ALL of us, right now",2,"Shirts up, everybody, nobody's embarrassed"}},
{"fw_ld7_pca_0046","panic_days",2,"reg=civilian,family,worker,rescue|tmp=fresh|day=0,4|mood=fear",{1,"Those people just ran past screaming and I didn't even look up",2,"Me neither",1,"God forgive me, I didn't even LOOK",2,"What were you gonna do, tackle 'em?"}},
{"fw_ld7_pca_0047","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=sad",{1,"I dropped the formula, the whole can, it's all over the floor",2,"Scoop it up, it's still good",1,"There's dirt in it, there's glass-",2,"Scoop it, I'll strain it through a sock, give it here"}},
{"fw_ld7_pca_0048","panic_days",2,"reg=civilian,family,worker,rescue|tmp=fresh|day=0,4|mood=angry",{1,"I was not gonna be like this, I was gonna be calm, I was gonna HELP people",2,"Nobody's calm",1,"I wet myself in the Piggly Wiggly, I'm telling you right now",2,"Then you're honest, that's more than half of 'em out there"}},
{"fw_ld7_pca_0049","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=fear",{1,"There's a man on channel nineteen just saying \"anybody\" over and over",2,"Anybody what?",1,"Just \"anybody, anybody out there,\" like he's got nothing else left",2,"Turn it off, I can't, turn it off"}},
{"fw_ld7_pca_0050","panic_days",2,"reg=civilian,family,worker,rescue|tmp=fresh|day=0,4|mood=fear",{1,"Did you see that little boy just standing in the middle of the yard?",2,"I saw",1,"Why didn't anybody go get him?",2,"Because he turned around, that's why, he turned around and his-- no, I'm not saying it"}},
{"fw_ld7_pca_0051","panic_days",3,"reg=civilian,family,worker,rescue|day=0,4|mood=fear",{1,"Somebody's at the gate, he's yelling for help, listen to him!",2,"Don't open it",3,"He's BEGGING, he's got blood on his shirt!",2,"That's how they get you to open up, he stays outside",1,"God forgive us, I can't listen to this"}},
{"fw_ld7_pca_0052","panic_days",2,"reg=civilian,family,worker,rescue|tmp=fresh|day=0,4|mood=fear",{1,"Mom, Mom, MOM, we have to go, we have to go right now",2,"Sit down. Let me think a second",1,"You've been thinking! Mom, we haven't got time!",2,"I said sit DOWN. I'm scared too, just... sit down"}},
{"fw_ld7_pca_0053","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=grim",{1,"I've been through the whole AM dial twice, there's nothing but a preacher and a hiss",2,"Try the FM",1,"FM's got one station and it's just a song on a loop",2,"What song?",1,"Does it matter?? It's the same four minutes over and over"}},
{"fw_ld7_pca_0054","panic_days",3,"reg=civilian,family,worker,rescue|day=0,4|mood=fear",{1,"Okay, head count, everybody say your name, loud",2,"Lonnie",3,"Teresa",2,"That's only two, who's the third? WHO'S THE THIRD?",3,"It's me, I'm Teresa, you said it twice, calm down"}},
{"fw_ld7_pca_0055","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=sad",{1,"I can't remember Janie's number, I've called it a hundred times and now I can't remember it",2,"It starts with four-two-two",1,"Four-two-two- no, no, what comes next, I know this",2,"It doesn't matter, the phones are dead"}},
{"fw_ld7_pca_0056","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=angry",{1,"They said stay in the shelter, we ARE in the shelter, so what's next?!",2,"Maybe they just meant stay",1,"For how long? How long, who said how long?",2,"Nobody said, nobody's saying a thing, that's the problem"}},
{"fw_ld7_pca_0057","panic_days",2,"reg=civilian,family,worker,rescue|tmp=fresh|day=0,4|mood=fear",{1,"I'm not going out there, you can't make me",2,"What if we needed water?",1,"Then we'd need water! I'm still scared of ending up DEAD",2,"I know. We'd have to make a plan, not just tell you to go"}},
{"fw_ld7_pca_0058","panic_days",3,"reg=civilian,family,worker,rescue|day=0,4|mood=sad",{1,"Somebody has to tell Mrs. Combs about Wayne",2,"Not me",3,"Not me either, I can't, I just can't look at her",1,"Then she's gonna sit up all night waiting on him",2,"...fine, I'll go, give me a minute, I need a minute"}},
{"fw_ld7_pca_0059","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=fear",{1,"Where were you when it started?",2,"Dairy Queen, I was ordering a Blizzard, can you believe that?",1,"A Blizzard!",2,"A woman came through the glass and I dropped it, I paid for it and I dropped it"}},
{"fw_ld7_pca_0060","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=grim",{1,"The TV was on and they cut to some reporter just running, camera all over the place",2,"Then what?",1,"Then the screen went to the colored bars and that horrible tone",2,"I saw the same thing, I thought it was a movie, I really did"}},
{"fw_ld7_pca_0061","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=calm",{1,"I'm a nurse, I should be helping somebody",2,"You can't help everybody",1,"I can help ONE person, why aren't I helping one person?",2,"Because you're here with us, and we're glad, that's why"}},
{"fw_ld7_pca_0062","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=angry",{1,"My boss called and said come in anyway, so I went",2,"And?",1,"Nobody there, lights on, coffee still going, a half-eaten sandwich",2,"Hope you took the sandwich"}},
{"fw_ld7_pca_0063","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=grim",{1,"Convoys went north, then south, then north again",2,"They don't know where to go either",1,"That's not funny, that's terrifying",2,"I'm not laughing"}},
{"fw_ld7_pca_0064","panic_days",3,"reg=civilian,family,worker,rescue|day=0,4|mood=fear",{1,"Do we tell the kids?",2,"They already know, they're not stupid",3,"They know there's something bad, they don't know how bad",1,"I'd like to keep it that way a little longer",2,"Then keep 'em away from the front of the house"}},
{"fw_ld7_pca_0065","panic_days",2,"reg=civilian,family,worker,rescue|tmp=fresh|day=0,4|mood=sad",{1,"I gotta pick up my little girl from day care at five",2,"It's past five",1,"I know it is, I know, I keep looking at my watch, I just need to go get her",2,"Where is it?",1,"Over in Vine Grove, three miles, I can't"}},
{"fw_ld7_pca_0066","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=sad",{1,"Reds game was on, the whole bottom of the sixth, and then it just cut to the beep",2,"I had the radio going too",1,"Even the man doing the game stopped mid-sentence",2,"What was he saying?",1,"\"And the pitch-\" that's it, \"and the pitch-\""}},
{"fw_ld7_pca_0067","panic_days",2,"reg=civilian,family,worker,rescue|tmp=fresh|day=0,4|mood=fear",{1,"Did you hear that? Was that a voice?",2,"It's a TV, somebody left a TV on",1,"Nobody's home on this whole side, I checked",2,"Then it's a radio, it's a radio, it's NOT a person, shut up"}},
{"fw_ld7_pca_0068","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=fear",{1,"Dolan's wife is out in their yard calling him, calling him like it's supper",2,"She doesn't see him",1,"He's RIGHT THERE, he's right behind the hedge!",2,"Don't yell, she's gonna- Linda! Linda, come away from there!"}},
{"fw_ld7_pca_0069","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=sad",{1,"I want to go to Mama's in Rosewood",2,"You can't, they've got Rosewood blocked off, the Guard turned everybody back",1,"I don't care what the Guard said, it's my MOTHER",2,"Then I'm going with you, because you'll get yourself killed alone"}},
{"fw_ld7_pca_0070","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=fear",{1,"You're sweating, why are you sweating?",2,"It's July!",1,"You're SHAKING, show me your arm",2,"Get away from me! Nobody bit me, nobody did, I did NOT get bit!"}},
{"fw_ld7_pca_0071","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=grim",{1,"We should get a gun in every room",2,"We only have the one",1,"Then we should get more",2,"From where? From who? Who's selling guns on a day like this?"}},
{"fw_ld7_pca_0072","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=sad",{1,"The cat's gone, Mittens got out when we ran",2,"She'll turn up",1,"She never goes out, she's a house cat, she doesn't know anything",2,"Cats are better at this than we are, trust- she'll be fine"}},
{"fw_ld7_pca_0073","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=funny",{1,"At least I got out of my dentist appointment, hahaha",2,"Monday at nine, right?",1,"Eight-thirty, I got a cavity, hahaha- oh God, I'm never gonna get that filled",2,"Don't, don't, we were doing so good"}},
{"fw_ld7_pca_0074","panic_days",2,"reg=civilian,family,worker,rescue|tmp=fresh|day=0,4|mood=fear",{1,"My knees won't work, they just stopped",2,"Lean on me",1,"I can't feel my legs, I saw what he did to- I can't feel my legs",2,"Then I'm carrying you, hold on, I'm gonna carry you"}},
{"fw_ld7_pca_0075","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=fear",{1,"I gotta pee",2,"Hold it",1,"I can't hold it, I've been holding it for two hours",2,"Then go in the corner, I'm not opening anything, I'm not going outside"}},
{"fw_ld7_pca_0076","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=angry",{1,"Stop reading the Bible out loud, you're making it worse",2,"It's the only thing that helps me",1,"You're reading the part about the plagues!",2,"I'm just going in order, it's what comes next"}},
{"fw_ld7_pca_0077","panic_days",2,"reg=civilian,family,worker,rescue|tmp=fresh|day=0,4|mood=fear",{1,"My ex-husband walked in. I hugged him. Me, hugging him",2,"Is he alright?",1,"He's alive. I had him in my arms and he was alive",2,"Hang on to him a second. I'll find you a chair"}},
{"fw_ld7_pca_0078","panic_days",3,"reg=civilian,family,worker,rescue|day=0,4|mood=fear",{1,"He's fine, he's just sleeping, leave him be",2,"He hasn't moved in an hour",3,"Is he breathing? Check if he's breathing",1,"He's SLEEPING, I said, don't touch him, don't you touch him",2,"Then why are you crying?"}},
{"fw_ld7_pca_0079","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=grim",{1,"Everybody's heading for the fort, the fort's the Army, the Army'll protect us",2,"Fort's got a gate and the gate's got guns",1,"Pointed which way?",2,"...I didn't wait around to see"}},
{"fw_ld7_pca_0080","panic_days",3,"reg=civilian,family,worker,rescue|day=0,4|mood=fear",{1,"There's somebody on a loudspeaker, I think it's the mayor",2,"What's he saying?",3,"Can't tell, it's all garbled, something something remain-",1,"Remain what? Remain calm? Remain INDOORS? What?!"}},
{"fw_ld7_pca_0081","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=sad",{1,"Nobody's cooking, we're eating cereal dry out of the box",2,"Better than nothing",1,"It's the Fruity Pebbles, the kids' favorite, they're not even excited",2,"That's the worst part, a kid not excited about Fruity Pebbles"}},
{"fw_ld7_pca_0082","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=grim",{1,"We could cross into Ohio",2,"Bridges are shut",1,"Boat, then",2,"You have a boat?",1,"I know a guy who has a boat... knew a guy, I don't know anymore"}},
{"fw_ld7_pca_0083","panic_days",2,"reg=civilian,family,worker,rescue|tmp=fresh|day=0,4|mood=sad",{1,"I can't leave without my guitar",2,"Your GUITAR?",1,"My dad gave it to me, it's the only thing I've got left of him",2,"Fine, fine, grab it, grab it fast, we're not waiting"}},
{"fw_ld7_pca_0084","panic_days",3,"reg=civilian,family,worker,rescue|day=0,4|mood=fear",{1,"What if it's us? What if we already got it and just don't know?",2,"Don't say that",3,"She's right, how would we know? How long does it take?",2,"I'd feel it, I'd feel different, wouldn't I?",1,"I feel different, I feel awful, but that's just terror"}},
{"fw_ld7_pca_0085","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=sad",{1,"I told the kids we're camping",2,"Camping, with no tent?",1,"They like camping, it's the only word I could think of",2,"Then we're camping, we're gonna roast marshmallows and everything, I guess"}},
{"fw_ld7_pca_0086","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=fear",{1,"I still remember worrying about that boombox. Couldn't stop thinking who might hear it",2,"It was the only music we'd found",1,"I know. I hated asking you to turn it off",2,"When we did, I hated how loud the quiet felt too"}},
{"fw_ld7_pca_0087","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=sad",{1,"He was a good dog, he was a real good dog",2,"Don't",1,"He barked and barked and they all went for him instead of the house",2,"I know, I know he did, he did, that's why we're alive"}},
{"fw_ld7_pca_0088","panic_days",2,"reg=civilian,family,worker,rescue|tmp=fresh|day=0,4|mood=fear",{1,"I saw my dad out in the pasture, standing real still",2,"Your dad's in Georgia",1,"Then who was that?? Who was that in his hat??",2,"Come away from the glass, come away"}},
{"fw_ld7_pca_0089","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=grim",{1,"Kids' school picture day was Monday, I never even got the order form back",2,"Why are you thinking about that?",1,"Because it's something I can fix, because it's small",2,"Go ahead, find a pen, fill it out, I'll watch the baby"}},
{"fw_ld7_pca_0090","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=fear",{1,"I hear scratching, something's scratching at the back",2,"It's the dog",1,"We don't HAVE a dog",2,"...then it's a branch, tell me it's a branch"}},
{"fw_ld7_pca_0091","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=angry",{1,"Why's it always the loud ones who survive? Look at Wade, hollering up and down the hall",2,"Wade's keeping us awake",1,"Wade's gonna bring every one of them down on us!",2,"Then tell him yourself, I'm not touching that man"}},
{"fw_ld7_pca_0092","panic_days",2,"reg=civilian,family,worker,rescue|tmp=fresh|day=0,4|mood=fear",{1,"Please, please tell me you locked it",2,"I locked it",1,"Check! Check again!",2,"I checked four times, it's locked, it's locked, it's LOCKED"}},
{"fw_ld7_pca_0093","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=sad",{1,"Last thing I said to my sister was that she looked tired",2,"Oh, honey",1,"That's it, \"you look tired,\" that's what I said, I didn't even hug her",2,"You'll tell her to her face, you'll find her"}},
{"fw_ld7_pca_0094","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=grim",{1,"How many days of food do we have?",2,"If we skip lunch, three",1,"And if we skip dinner?",2,"Then four, and then we're skipping everything, so let's not do math"}},
{"fw_ld7_pca_0095","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=fear",{1,"Did the baby stop crying?",2,"Yeah, a minute ago",1,"Is he breathing? Is HE BREATHING?",2,"He's fine, he's asleep, he finally cried himself out, look"}},
{"fw_ld7_pca_0096","panic_days",2,"reg=civilian,family,worker,rescue|tmp=fresh|day=0,4|mood=fear",{1,"Stop looking out the glass",2,"I can't help it, somebody's out there",1,"Somebody's always out there, that's why we're not looking!",2,"But what if it's Rita, what if she needs us?"}},
{"fw_ld7_pca_0097","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=angry",{1,"My nerves are shot, I'm gonna scream, I'm telling you right now I'm gonna scream",2,"You can't scream",1,"Then give me something to hit, give me a pillow",2,"I can't give you a pillow. I can stay here while you get through the next minute"}},
{"fw_ld7_pcb_0001","panic_days",3,"reg=civilian,family,worker,rescue|day=0,4|mood=fear",{1,"I keep hearing that night over again. Somebody yelling they're in the yard",2,"Telling everybody to get away from the glass?",3,"All I could think was, where are the kids?",1,"I kept telling you Rita was with them. Hoped saying it twice would get through",3,"I needed somebody to say it twice. Couldn't take in one word the first time"}},
{"fw_ld7_pcb_0002","panic_days",2,"reg=civilian,family,worker,rescue|tmp=fresh|day=0,4|mood=fear",{1,"shh... listen...",2,"I don't hear anything",1,"exactly, that's what I don't like, it stopped",2,"Maybe it left",1,"don't say maybe, I can't take maybe right now"}},
{"fw_ld7_pcb_0003","panic_days",2,"reg=civilian,family,worker,rescue|tmp=fresh|day=0,4|mood=fear",{1,"Nope nope nope, I am not doing this, take me home",2,"Hey, hey, look at me",1,"There's one in the- it's RIGHT THERE",2,"I see it, it's not coming this way, breathe",1,"I can't breathe, my chest- my chest is-",2,"In through your nose, come on, slow, I got you"}},
{"fw_ld7_pcb_0004","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=fear",{1,"I remember losing my keys the night we took the baby to hospital",2,"You thought she wasn't breathing right?",1,"Couldn't think. Found the keys in my own hand",2,"You were scared. That doesn't make you a bad parent"}},
{"fw_ld7_pcb_0005","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=fear",{1,"Move! We have to MOVE!",2,"I'm not leaving Mama",1,"She's gone, she's gone, we saw it!",2,"DON'T SAY THAT! Don't you say that!",1,"Then carry her, I'll carry her, just MOVE"}},
{"fw_ld7_pcb_0006","panic_days",3,"reg=civilian,family,worker,rescue|day=0,4|mood=fear",{1,"Heard they're handing out masks at the VFW",2,"I heard it was shots, like vaccines",3,"I heard they're piling bodies up at the VFW",1,"Who told you that?!",3,"A guy at the Citgo, he was white as a ghost, he wouldn't stop shaking"}},
{"fw_ld7_pcb_0007","panic_days",2,"reg=civilian,family,worker,rescue|tmp=fresh|day=0,4|mood=fear",{1,"Go left, LEFT",2,"Which left?!",1,"My left- no, your- ugh, toward the church!",2,"It's blocked, there's somebody in the way!",1,"Then go around, GO AROUND, don't stop!"}},
{"fw_ld7_pcb_0008","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=fear",{1,"how many",2,"two, I think, maybe three",1,"are they looking?",2,"one is, don't move, don't even blink",1,"I'm gonna blink",2,"...okay, blink slow"}},
{"fw_ld7_pcb_0009","panic_days",2,"reg=civilian,family,worker,rescue|tmp=fresh|day=0,4|mood=fear",{1,"We should leave while-",2,"And go where, where would-",1,"Anywhere, the school, the church, I don't-",2,"The school's full, the church is-",1,"Then the bridge, we could-",2,"STOP, stop, stop talking, just stop"}},
{"fw_ld7_pcb_0010","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=fear",{1,"So I'm in the Kroger, right, getting milk, because we always get milk",2,"Milk",1,"And this lady comes running down the aisle, no shoes, screaming, and behind her this man-",2,"Don't",1,"-this man in a Kroger apron, I KNEW him, he used to bag my groceries",2,"Stop, please, I can't hear the rest"}},
{"fw_ld7_pcb_0011","panic_days",3,"reg=civilian,family,worker,rescue|day=0,4|mood=fear",{1,"WHERE'S THE BABY",2,"She's right where I put her, calm down",1,"She is NOT where you put her!",2,"Oh God, oh God, she was just- she was just-",3,"Here! She's here, she crawled under the table, she's fine, she's laughing"}},
{"fw_ld7_pcb_0012","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=grim",{1,"How much food have we got?",2,"Plenty",1,"Define plenty",2,"Two cans of green beans and a box of Triscuits, but I said it with confidence"}},
{"fw_ld7_pcb_0013","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=funny",{1,"When our phone quit, I said, bright side, no more phone bill",2,"Your phone was dead and that was your first thought?",1,"That's what I said, bright side",2,"Hahaha- you're sick, I'm gonna stop laughing in a second, give me a second"}},
{"fw_ld7_pcb_0014","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=angry",{1,"Turn the radio on, we need to hear something!",2,"Noise brings them!",1,"The radio's not noise, it's NEWS!",2,"To them it's noise, they don't care what the weather is, turn it OFF"}},
{"fw_ld7_pcb_0015","panic_days",2,"reg=civilian,family,worker,rescue|tmp=fresh|day=0,4|mood=fear",{1,"They're just sick people, they need help, somebody should help them",2,"They went after the Pruitts",1,"They're SICK, they're scared, they don't know what they're doing!",2,"Then go out there and tell them it's okay, go ahead, I'll watch from here"}},
{"fw_ld7_pcb_0016","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=fear",{1,"It's like a movie, right? Like one of those old movies?",2,"Don't",1,"I'm just saying-",2,"DON'T name it, if you name it, it's real, just don't"}},
{"fw_ld7_pcb_0017","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=fear",{1,"Breathe into the bag",2,"It smells like onions",1,"Breathe anyway, in, out, in",2,"I'm- I'm dizzy, I'm gonna- hold the bag, hold it!"}},
{"fw_ld7_pcb_0018","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=grim",{1,"I'm just gonna run out and grab my cigarettes",2,"Are you out of your MIND",1,"It's my last pack of Winstons!",2,"You're going to die for a pack of Winstons, in front of me, I have to watch that?"}},
{"fw_ld7_pcb_0019","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=fear",{1,"Why is every siren in the county going? Is that the tornado one?",2,"Tornado's the long one, that's the fire one",1,"They're all going at once!",2,"Then it's all of them, the whole county's got a different reason, and none of 'em are good"}},
{"fw_ld7_pcb_0020","panic_days",2,"reg=civilian,family,worker,rescue|tmp=fresh|day=0,4|mood=fear",{1,"What was THAT? That shook my teeth!",2,"Something big, I felt it in my feet",1,"What else is that loud?",2,"Something from the fort, I don't know, don't ask me what"}},
{"fw_ld7_pcb_0021","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=sad",{1,"Mommy, the man outside is hurt, he needs a Band-Aid",2,"Come here, come away from there, baby",1,"But he's bleeding, I can see it-",2,"Come AWAY, come here, close your eyes, keep them closed, that's it, that's it"}},
{"fw_ld7_pcb_0022","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=sad",{1,"It's Hank, it's HANK, that's Hank at the gate!",2,"It's not Hank anymore",1,"He's still got his wedding ring on! He's still got his ring!",2,"I know, I know he does, step back, step away from the gate"}},
{"fw_ld7_pcb_0023","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=fear",{1,"Don't shoot, don't shoot, he's not- he's just a kid!",2,"He's walking funny, he's not talking!",1,"He's scared, he's hurt!",2,"Then why isn't he answering us? WHY ISN'T HE ANSWERING?"}},
{"fw_ld7_pcb_0024","panic_days",2,"reg=civilian,family,worker,rescue|tmp=fresh|day=0,4|mood=fear",{1,"I saw somebody stand up that shouldn't have been able to stand up",2,"What do you mean",1,"I mean he was on the ground, he'd been on the ground for an hour, and then he just stood up",2,"Stop, no, I don't want that to be true"}},
{"fw_ld7_pcb_0025","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=angry",{1,"Who made the decision to wait for help? Because I'd like a word with them",2,"We all decided",1,"Well I was wrong, I was wrong, nobody's coming, nobody was ever coming!",2,"You don't know that, we don't know that yet"}},
{"fw_ld7_pcb_0026","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=fear",{1,"Is anybody out there? Hello? HELLO?",2,"Quiet!",1,"If somebody answers, we're saved!",2,"If somebody answers, we're found, and I don't know which is worse"}},
{"fw_ld7_pcb_0027","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=fear",{1,"My phone's ringing",2,"Your phone's dead",1,"No, it's ringing, listen, in the next room, listen!",2,"That's not a phone, that's a- no, it is, it IS, go! Go answer it!"}},
{"fw_ld7_pcb_0028","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=sad",{1,"Mama taught me to sew, so I've been sewing",2,"Sewing what?",1,"A curtain, for the front, so nobody can see in",2,"It's a good curtain, it's really, it's a beautiful curtain"}},
{"fw_ld7_pcb_0029","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=fear",{1,"I counted the shells, there's eleven, I counted eleven",2,"Count again",1,"Eleven, still eleven",2,"Then that's eleven, we've got eleven chances, don't waste one"}},
{"fw_ld7_pcb_0030","panic_days",3,"reg=civilian,family,worker,rescue|day=0,4|mood=grim",{1,"Who's gonna be the one to go out for water?",2,"Not me",3,"Not me either",1,"Fine, we flip, I got a quarter, heads you go, tails you go",2,"That's not how coins work!"}},
{"fw_ld7_pcb_0031","panic_days",2,"reg=civilian,family,worker,rescue|tmp=fresh|day=0,4|mood=fear",{1,"He's coming around the side, he's coming around the side!",2,"Lock it, LOCK IT!",1,"It is locked! It's been locked!",2,"Then why's it moving? WHY'S IT MOVING?!"}},
{"fw_ld7_pcb_0032","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=fear",{1,"I think the dog's trying to tell us something",2,"He's just barking",1,"No, he keeps going to the same corner, listen to him whine",2,"Then somebody's in that corner, or something, back away"}},
{"fw_ld7_pcb_0033","panic_days",2,"reg=civilian,family,worker,rescue|day=0,4|mood=sad",{1,"I never even said goodbye",2,"To who?",1,"To anybody, I just left, I grabbed my keys and I left, I didn't say it",2,"They know, I'd bet money they know"}},
}
